                mem_r_EX         <= 1'b0;
                isFlushed        <= 1'b1;
                csr_rw_EX        <= 1'b0;
                csr_w_imm_mux_EX <= 1'b0;
                mret_EX          <= 1'b0;
                exp_vector_EX    <= 2'b0;
            end
            else begin
                PCurrent_EX      <= PCurrent_ID;
                IR_EX            <= IR_ID;
                rs1_EX           <= rs1_addr;
                rs2_EX           <= rs2_addr;
                A_EX             <= rs1_data;
