                    output reg[3:0]  exp_vector_WB
                );

    // 实现：MEM/WB 流水寄存器
    // On reset: clear rd_WB, RegWrite_WB, IR_WB, PCurrent_WB, isFlushed, exp_vector_WB to 0.
    // When EN is asserted:
    //   - If flush: clear write signals and set isFlushed, pass PCurrent_MEM to PCurrent_WB.
    //   - Else: latch all input signals to their corresponding output registers.
    always @(posedge clk) begin
        if (rst) begin
            PCurrent_WB   <= 32'b0;
            IR_WB         <= 32'b0;
            ALUO_WB       <= 32'b0;
            MDR_WB        <= 32'b0;
            rd_WB         <= 5'b0;
            DatatoReg_WB  <= 1'b0;
            RegWrite_WB   <= 1'b0;
            isFlushed     <= 1'b0;
            exp_vector_WB <= 4'b0;
        end
        else if (EN) begin
            if (flush) begin                    // 清除写信号
                PCurrent_WB   <= PCurrent_MEM;
                IR_WB         <= 32'h00000000;
                ALUO_WB       <= 32'b0;
                MDR_WB        <= 32'b0;
                rd_WB         <= 5'b0;
                DatatoReg_WB  <= 1'b0;
                RegWrite_WB   <= 1'b0;
                isFlushed     <= 1'b1;
                exp_vector_WB <= 4'b0;
            end
            else begin
                PCurrent_WB   <= PCurrent_MEM;
                IR_WB         <= IR_MEM;
                ALUO_WB       <= ALUO_MEM;
                MDR_WB        <= Datai;
                rd_WB         <= rd_MEM;
                DatatoReg_WB  <= DatatoReg_MEM;
                RegWrite_WB   <= RegWrite_MEM;
                isFlushed     <= 1'b0;
                exp_vector_WB <= exp_vector_MEM;
            end
        end
    end
endmodule############ Regs ############
