module tb_sort;
    reg clk = 0, rst = 1;
    wire [31:0] wb_pc, wb_inst, mem_addr, mem_data, debug_data;
    wire [7:0] uart_char;
    wire uart_valid;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(debug_data),
        .clk(clk), .rst(rst), .wb_pc(wb_pc), .wb_inst(wb_inst),
        .mem_addr(mem_addr), .mem_data(mem_data), .interrupter(1'b0),
        .sim_uart_char_out(uart_char), .sim_uart_char_valid(uart_valid));

    integer ftrace, fuart, fstate, i;
    integer ncycle = 0, ncommit = 0, nchar = 0;
    integer n_stall = 0, n_flush = 0, n_fwd_a = 0, n_fwd_b = 0, n_fwd_ls = 0;
    integer halt_cycle = -1;
    integer xerr = 0;
    reg [31:0] prev_wbpc;

    always #5 clk = ~clk;

    initial begin
        ftrace = $fopen("dut_trace.txt", "w");
        fuart  = $fopen("dut_uart.txt", "w");
        #12 rst = 0;
    end

    // UART capture (sample the valid pulse)
    always @(posedge clk) begin
        if (!rst && uart_valid) begin
            $fwrite(fuart, "%c", uart_char);
            nchar = nchar + 1;
        end
    end

    // WB commit trace + hazard statistics, sampled just before each rising edge
    always @(negedge clk) begin
        if (!rst) begin
            ncycle = ncycle + 1;
            if (core.reg_FD_stall)   n_stall = n_stall + 1;
            if (core.reg_FD_flush)   n_flush = n_flush + 1;
            if (core.forward_ctrl_A != 2'b00) n_fwd_a = n_fwd_a + 1;
            if (core.forward_ctrl_B != 2'b00) n_fwd_b = n_fwd_b + 1;
            if (core.forward_ctrl_ls) n_fwd_ls = n_fwd_ls + 1;

            if (wb_inst !== 32'h0) begin
                if (^{wb_pc, wb_inst, core.rd_WB, core.RegWrite_WB} === 1'bx) begin
                    if (xerr < 10) $display("XPROP at cycle %0d: pc=%h inst=%h rd=%h rw=%b",
                        ncycle, wb_pc, wb_inst, core.rd_WB, core.RegWrite_WB);
                    xerr = xerr + 1;
                end
                if (core.RegWrite_WB && (^core.wt_data_WB === 1'bx)) begin
                    if (xerr < 10) $display("XDATA at cycle %0d: pc=%h inst=%h wt=%h",
                        ncycle, wb_pc, wb_inst, core.wt_data_WB);
                    xerr = xerr + 1;
                end
                $fwrite(ftrace, "%08x %08x %2d %d %08x\n", wb_pc, wb_inst,
                    core.RegWrite_WB ? core.rd_WB : 5'd0, core.RegWrite_WB,
                    core.RegWrite_WB ? core.wt_data_WB : 32'h0);
                ncommit = ncommit + 1;
            end

            // halt detection: PC_IF parked on a self-loop (jal x0,0)
            if (halt_cycle < 0 && core.PC_IF == 32'h0000021c &&
                core.PC_ID == 32'h0000021c && core.PC_EXE == 32'h0000021c) begin
                halt_cycle = ncycle;
            end
        end
    end

    initial begin
        #12;
        while (ncycle < 200000 && (halt_cycle < 0 || ncycle < halt_cycle + 8))
            @(negedge clk);
        $fclose(ftrace);
        $fclose(fuart);
        fstate = $fopen("dut_state.txt", "w");
        $fwrite(fstate, "HALTPC %08x\n", core.PC_IF);
        $fwrite(fstate, "REG  0 %08x\n", 32'h0);
        for (i = 1; i < 32; i = i + 1)
            $fwrite(fstate, "REG %2d %08x\n", i, core.register.register[i]);
        for (i = 0; i < 256; i = i + 1)
            $fwrite(fstate, "RAM %3d %02x\n", i, core.data_ram.data[i]);
        $fclose(fstate);
        $display("CYCLES=%0d COMMITS=%0d CHARS=%0d HALT_CYCLE=%0d XERR=%0d",
            ncycle, ncommit, nchar, halt_cycle, xerr);
        $display("STATS stall=%0d flush=%0d fwdA=%0d fwdB=%0d fwdLS=%0d",
            n_stall, n_flush, n_fwd_a, n_fwd_b, n_fwd_ls);
        $finish;
    end
endmodule

