    reg clk = 0, rst = 1;
    wire [31:0] wb_pc, wb_inst, mem_addr, mem_data, debug_data;
    wire [7:0] uart_char;
    wire uart_valid;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(debug_data),
        .clk(clk), .rst(rst), .wb_pc(wb_pc), .wb_inst(wb_inst),
        .mem_addr(mem_addr), .mem_data(mem_data), .interrupter(1'b0),
        .sim_uart_char_out(uart_char), .sim_uart_char_valid(uart_valid));

    integer ftrace, fstate, i;
    integer ncycle = 0, ncommit = 0, xerr = 0, same = 0, done = 0;
    integer n_stall = 0, n_flush = 0, n_fwd_ls = 0;
    integer f01 = 0, f10 = 0, f11 = 0, g01 = 0, g10 = 0, g11 = 0;
    reg [31:0] lastpc;

    always #5 clk = ~clk;
    initial begin
        ftrace = $fopen("dut_trace.txt", "w");
        #12 rst = 0;
    end

    always @(negedge clk) begin
        if (!rst && !done) begin
            ncycle = ncycle + 1;
            if (core.reg_FD_stall) n_stall = n_stall + 1;
            if (core.reg_FD_flush) n_flush = n_flush + 1;
            if (core.forward_ctrl_ls) n_fwd_ls = n_fwd_ls + 1;
            case (core.forward_ctrl_A) 2'b01: f01=f01+1; 2'b10: f10=f10+1; 2'b11: f11=f11+1; endcase
            case (core.forward_ctrl_B) 2'b01: g01=g01+1; 2'b10: g10=g10+1; 2'b11: g11=g11+1; endcase

            if (wb_inst !== 32'h0) begin
                if ((^{wb_pc, wb_inst} === 1'bx) ||
                    (core.RegWrite_WB === 1'bx) ||
                    (core.RegWrite_WB && (^core.wt_data_WB === 1'bx))) begin
                    if (xerr < 10) $display("X-PROP cycle %0d pc=%h inst=%h rw=%b wt=%h",
                        ncycle, wb_pc, wb_inst, core.RegWrite_WB, core.wt_data_WB);
                    xerr = xerr + 1;
                end
                $fwrite(ftrace, "%08x %08x %2d %d %08x\n", wb_pc, wb_inst,
                    core.RegWrite_WB ? core.rd_WB : 5'd0, core.RegWrite_WB,
                    core.RegWrite_WB ? core.wt_data_WB : 32'h0);
                ncommit = ncommit + 1;
            end

            if (core.PC_IF == lastpc) same = same + 1; else same = 0;
            lastpc = core.PC_IF;
            if (same > 6) done = 1;
        end
    end

    initial begin
        #12;
        while (ncycle < 100000 && !done) @(negedge clk);
        @(negedge clk);
        $fclose(ftrace);
        fstate = $fopen("dut_state.txt", "w");
        $fwrite(fstate, "HALTPC %08x\n", core.PC_IF);
        $fwrite(fstate, "REG  0 %08x\n", 32'h0);
        for (i = 1; i < 32; i = i + 1)
            $fwrite(fstate, "REG %2d %08x\n", i, core.register.register[i]);
        for (i = 0; i < 256; i = i + 1)
            $fwrite(fstate, "RAM %3d %02x\n", i, core.data_ram.data[i]);
        $fclose(fstate);
        $display("CYCLES=%0d COMMITS=%0d XERR=%0d HALTPC=%h", ncycle, ncommit, xerr, core.PC_IF);
        $display("STATS stall=%0d flush=%0d fwdA(01/10/11)=%0d/%0d/%0d fwdB(01/10/11)=%0d/%0d/%0d fwdLS=%0d",
            n_stall, n_flush, f01, f10, f11, g01, g10, g11, n_fwd_ls);
        $finish;
    end
endmodule

